using LittleLeo.Events;
using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "ChooseTargetStateJoystickAction", menuName = "Data/Battle/Actions/ChooseTargetStateJoystickAction")]
public class ChooseTargetStateJoystickAction : ChooseTargetStateAction
{
	[SerializeField]
	private VoidEvent OnStartAnyChooseTargetStateJoystick;

	public override void OnStartState()
	{
		base.OnStartState();
		if (chooseSelf)
		{
			base.inputManager.AddCurrentActionInstanceOwnerToTargetInstanceList();
		}
		else
		{
			for (int i = 0; i < targetUnits.Count; i++)
			{
				targetUnits[i].PopulateTargetInstanceLists();
			}
			for (int j = 0; j < targetUnits.Count; j++)
			{
				targetUnits[j].AfterPopulateTargetInstanceLists();
			}
		}
		base.inputManager.GoToFirstTargetInstance();
		OnStartAnyChooseTargetStateJoystick.Raise();
	}

	public override void Execute(float d)
	{
		base.inputManager.TargetInstanceInput();
		if (base.inputManager.GetSelectButtonUp())
		{
			base.inputManager.KillActionInstanceMovementTween();
			TargetInstance currentTargetInstance = base.inputManager.CurrentTargetInstance;
			TargetSelected(currentTargetInstance);
		}
		base.inputManager.GetCancelButtonUpCancelBattleAction(base.actionInstance);
	}
}
